    pub open spec fn append_pre(
        &self,
        nid: NodeId,
        data: DT::View,
        ops: Seq<DT::WriteOperation>,
        inst: UnboundedLog::Instance<DT>,
        cb_inst: CyclicBuffer::Instance<DT>,
